using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using StockFlow.Data;
using StockFlow.Models;
namespace StockFlow.Controllers; [Authorize(Roles = "Admin,Manager,Procurement,StockClerk,Viewer")]
public class PurchasesController(ApplicationDbContext db) : Controller
{
    public async Task<IActionResult> Index() => View(await db.PurchaseOrders.Include(p => p.Supplier).OrderByDescending(p => p.CreatedAt).ToListAsync()); [Authorize(Roles = "Admin,Manager,Procurement")] public async Task<IActionResult> Create() { ViewBag.Suppliers = await db.Suppliers.Where(s => s.IsActive).OrderBy(s => s.Name).ToListAsync(); ViewBag.Products = await db.Products.Where(p => p.IsActive).OrderBy(p => p.Name).ToListAsync(); return View(new CreatePurchaseVm { Quantity = 1 }); }
    [HttpPost, ValidateAntiForgeryToken, Authorize(Roles = "Admin,Manager,Procurement")] public async Task<IActionResult> Create(CreatePurchaseVm vm) { var supplier = await db.Suppliers.FindAsync(vm.SupplierId); var product = await db.Products.FindAsync(vm.ProductId); if (supplier == null || product == null) ModelState.AddModelError("", "Choose a valid supplier and product."); if (!ModelState.IsValid) { ViewBag.Suppliers = await db.Suppliers.Where(s => s.IsActive).ToListAsync(); ViewBag.Products = await db.Products.Where(p => p.IsActive).ToListAsync(); return View(vm); } var po = new PurchaseOrder { OrderNumber = "PO-" + DateTime.UtcNow.ToString("yyyyMMddHHmmss") + Random.Shared.Next(10, 99), SupplierId = vm.SupplierId, ExpectedAt = vm.ExpectedAt, Notes = vm.Notes, CreatedBy = User.Identity?.Name ?? "unknown", Status = (vm.Quantity * vm.UnitCost >= 10000 ? PurchaseStatus.PendingApproval : PurchaseStatus.Ordered) }; po.Lines.Add(new PurchaseOrderLine { ProductId = vm.ProductId, QuantityOrdered = vm.Quantity, UnitCost = vm.UnitCost }); db.PurchaseOrders.Add(po); db.AuditLogs.Add(new AuditLog { UserEmail = po.CreatedBy, Action = "Created", EntityName = "PurchaseOrder", EntityId = po.OrderNumber, Details = $"Purchase order for {supplier!.Name}; status {po.Status}" }); await db.SaveChangesAsync(); TempData["Success"] = po.Status == PurchaseStatus.PendingApproval ? "Purchase order submitted for approval (R10,000+)." : "Purchase order created."; return RedirectToAction(nameof(Index)); }
    [Authorize(Roles = "Admin,Manager")] public async Task<IActionResult> Approve(int id) { var po = await db.PurchaseOrders.FindAsync(id); if (po == null) return NotFound(); if (po.Status != PurchaseStatus.PendingApproval) { TempData["Error"] = "Only orders pending approval can be approved."; return RedirectToAction(nameof(Index)); } po.Status = PurchaseStatus.Approved; po.ApprovedBy = User.Identity?.Name; po.ApprovedAt = DateTime.UtcNow; db.AuditLogs.Add(new AuditLog { UserEmail = po.ApprovedBy!, Action = "Approved", EntityName = "PurchaseOrder", EntityId = po.OrderNumber, Details = "Purchase approval recorded." }); await db.SaveChangesAsync(); TempData["Success"] = "Purchase order approved."; return RedirectToAction(nameof(Index)); }
    [Authorize(Roles = "Admin,Manager,StockClerk")] public async Task<IActionResult> Receive(int id) { var po = await db.PurchaseOrders.Include(x => x.Supplier).Include(x => x.Lines).ThenInclude(l => l.Product).FirstOrDefaultAsync(x => x.Id == id); return po == null ? NotFound() : View(po); }
    [HttpPost, ValidateAntiForgeryToken, Authorize(Roles = "Admin,Manager,StockClerk")] public async Task<IActionResult> Receive(int id, int lineId, int quantity) { var po = await db.PurchaseOrders.Include(x => x.Lines).ThenInclude(l => l.Product).FirstOrDefaultAsync(x => x.Id == id); if (po == null) return NotFound(); var line = po.Lines.FirstOrDefault(x => x.Id == lineId); if (line == null || quantity < 1 || line.QuantityReceived + quantity > line.QuantityOrdered || po.Status is PurchaseStatus.PendingApproval or PurchaseStatus.Rejected or PurchaseStatus.Cancelled or PurchaseStatus.Draft) { TempData["Error"] = "Invalid receipt quantity or order status."; return RedirectToAction(nameof(Receive), new { id }); } line.QuantityReceived += quantity; var p = line.Product!; p.QuantityOnHand += quantity; db.StockMovements.Add(new StockMovement { ProductId = p.Id, Type = MovementType.PurchaseReceipt, QuantityChange = quantity, BalanceAfter = p.QuantityOnHand, Reason = "Purchase order receipt", Reference = po.OrderNumber, PerformedBy = User.Identity?.Name ?? "unknown" }); po.Status = po.Lines.All(l => l.QuantityReceived == l.QuantityOrdered) ? PurchaseStatus.Received : PurchaseStatus.PartiallyReceived; await db.SaveChangesAsync(); TempData["Success"] = "Receipt recorded and stock updated."; return RedirectToAction(nameof(Receive), new { id }); }
}
